import{at as e,it as t,n,vt as r}from"./chunks/framework.BH1UGovZ.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireFrame Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireFrame/aireframe-v3-5-0.md","filePath":"aireblock-releases/AireFrame/aireframe-v3-5-0.md","lastUpdated":1795541592000}`),a={name:`aireblock-releases/AireFrame/aireframe-v3-5-0.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="aireframe-release-notes" tabindex="-1"><span class="fsc-product"><img src="/aireframe-icon.png"> AireFrame Release Notes</span> <a class="header-anchor" href="#aireframe-release-notes" aria-label="Permalink to “AireFrame Release Notes”">​</a></h1><blockquote><p><strong>Version:</strong> 3.5.0<br><strong>Release Date:</strong> 02 December 2026</p></blockquote><h2 id="summary-of-changes" tabindex="-1">Summary of Changes <a class="header-anchor" href="#summary-of-changes" aria-label="Permalink to “Summary of Changes”">​</a></h2><p>🚨 <strong>Critical Fixes</strong></p><ul><li>Faster and More Reliable Subject Updates (FRAME-2825)</li><li>Offline Viewing of PDFs on iOS (FRAME-2839)</li></ul><p>✨ <strong>New Features</strong></p><ul><li>Offline Working: Persisted Subject Downloads (FRAME-2779)</li><li>Mark All Notifications as Read (FRAME-2820)</li><li>Edit Linked and Stacked Datasets in Place (FRAME-2814)</li><li>Audit Trail for Configuration Import and Export (FRAME-2805)</li><li>View Withdrawn PDFs in a Widget (FRAME-2691)</li><li>Flexible Configuration Import (FRAME-2469)</li></ul><p>🐞 <strong>Bug Fixes</strong></p><ul><li>Viewing Form PDFs No Longer Requires List:User Permission (FRAME-2742)</li><li>Widget and Pipeline Lists Fail to Load (FRAME-2775)</li><li>Search on the Home Page Keeps Your Location (FRAME-2751)</li><li>Widget Action Menu Stays Within the Widget (FRAME-2769)</li></ul><h1 id="detailed-changes" tabindex="-1">Detailed Changes <a class="header-anchor" href="#detailed-changes" aria-label="Permalink to “Detailed Changes”">​</a></h1><h2 id="🐞-critical-fixes" tabindex="-1">🐞 Critical Fixes <a class="header-anchor" href="#🐞-critical-fixes" aria-label="Permalink to “🐞 Critical Fixes”">​</a></h2><h3 id="faster-and-more-reliable-subject-updates-frame-2825" tabindex="-1">Faster and More Reliable Subject Updates (FRAME-2825) <a class="header-anchor" href="#faster-and-more-reliable-subject-updates-frame-2825" aria-label="Permalink to “Faster and More Reliable Subject Updates (FRAME-2825)”">​</a></h3><div class="info custom-block"><p class="custom-block-title">Description</p><p>Subject updates are now faster and more reliable when many are made at once. This removes the occasional &quot;conflict&quot; errors that could interrupt integrations and automated tasks during busy periods.</p></div><h3 id="offline-viewing-of-pdfs-on-ios-frame-2839" tabindex="-1">Offline Viewing of PDFs on iOS (FRAME-2839) <a class="header-anchor" href="#offline-viewing-of-pdfs-on-ios-frame-2839" aria-label="Permalink to “Offline Viewing of PDFs on iOS (FRAME-2839)”">​</a></h3><div class="info custom-block"><p class="custom-block-title">Description</p><p>Fixes an issue where PDFs could not be viewed offline on iOS devices. If you download a subject record while online, you can now view its PDFs without an internet connection.</p></div><h2 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h2><h3 id="offline-working-persisted-subject-downloads-frame-2779" tabindex="-1">Offline Working: Persisted Subject Downloads (FRAME-2779) <a class="header-anchor" href="#offline-working-persisted-subject-downloads-frame-2779" aria-label="Permalink to “Offline Working: Persisted Subject Downloads (FRAME-2779)”">​</a></h3><div class="info custom-block"><p class="custom-block-title">Description</p><p>Subject downloads for offline use are now recorded, so you can see which colleagues have downloaded a subject. You can turn offline access on or off for a record at any time. When you reconnect, downloads are brought up to date automatically, and subject records that are no longer needed are cleaned up for you.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can see which colleagues have a subject record available offline, helping you understand who is working with the latest information.</p></div><h3 id="mark-all-notifications-as-read-frame-2820" tabindex="-1">Mark All Notifications as Read (FRAME-2820) <a class="header-anchor" href="#mark-all-notifications-as-read-frame-2820" aria-label="Permalink to “Mark All Notifications as Read (FRAME-2820)”">​</a></h3><div class="info custom-block"><p class="custom-block-title">Description</p><p>Adds a &quot;Mark all as read&quot; option to the notification menu, so you can clear all unread notifications in one action.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>No more clearing notifications one by one. Keep your inbox tidy with a single click.</p></div><h3 id="edit-linked-and-stacked-datasets-in-place-frame-2814" tabindex="-1">Edit Linked and Stacked Datasets in Place (FRAME-2814) <a class="header-anchor" href="#edit-linked-and-stacked-datasets-in-place-frame-2814" aria-label="Permalink to “Edit Linked and Stacked Datasets in Place (FRAME-2814)”">​</a></h3><div class="info custom-block"><p class="custom-block-title">Description</p><p>You can now edit the definition of linked and stacked datasets directly, including source data, filters, aggregators and stacked fields, without creating a new version. Changes that would break existing visualisations are checked for and prevented.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>Update your datasets quickly without re-pointing your dashboards and reports, with confidence that existing visualisations keep working.</p></div><h3 id="audit-trail-for-configuration-import-and-export-frame-2805" tabindex="-1">Audit Trail for Configuration Import and Export (FRAME-2805) <a class="header-anchor" href="#audit-trail-for-configuration-import-and-export-frame-2805" aria-label="Permalink to “Audit Trail for Configuration Import and Export (FRAME-2805)”">​</a></h3><div class="info custom-block"><p class="custom-block-title">Description</p><p>Importing or exporting configuration is now recorded in the audit trail.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You have a clear record of who imported or exported configuration and when, supporting governance and accountability for tenant administrators.</p></div><h3 id="withdrawn-pdfs-in-a-data-extracts-frame-2691" tabindex="-1">Withdrawn PDFs in a Data Extracts (FRAME-2691) <a class="header-anchor" href="#withdrawn-pdfs-in-a-data-extracts-frame-2691" aria-label="Permalink to “Withdrawn PDFs in a Data Extracts (FRAME-2691)”">​</a></h3><div class="info custom-block"><p class="custom-block-title">Description</p><p>Data extracts can now be configured to include withdrawn PDFs.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>Staff can find and review withdrawn documents when needed for workflow or compliance purposes.</p></div><h3 id="flexible-configuration-import-frame-2469" tabindex="-1">Flexible Configuration Import (FRAME-2469) <a class="header-anchor" href="#flexible-configuration-import-frame-2469" aria-label="Permalink to “Flexible Configuration Import (FRAME-2469)”">​</a></h3><div class="info custom-block"><p class="custom-block-title">Description</p><p>When importing configuration, you can now choose &quot;Everything&quot; to import all of it, or &quot;Partial&quot; to import everything except structural entities.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>Import a tenant&#39;s configuration without bringing across its structure, so you can keep your existing structural entities as they are.</p></div><h2 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h2><h3 id="viewing-form-pdfs-no-longer-requires-list-user-permission-frame-2742" tabindex="-1">Viewing Form PDFs No Longer Requires List:User Permission (FRAME-2742) <a class="header-anchor" href="#viewing-form-pdfs-no-longer-requires-list-user-permission-frame-2742" aria-label="Permalink to “Viewing Form PDFs No Longer Requires List:User Permission (FRAME-2742)”">​</a></h3><div class="info custom-block"><p class="custom-block-title">Description</p><p>Fixes an issue where users needed the &quot;List:User&quot; permission to view a form PDF. Form PDFs can now be viewed without that permission.</p></div><h3 id="widget-and-pipeline-lists-fail-to-load-frame-2775" tabindex="-1">Widget and Pipeline Lists Fail to Load (FRAME-2775) <a class="header-anchor" href="#widget-and-pipeline-lists-fail-to-load-frame-2775" aria-label="Permalink to “Widget and Pipeline Lists Fail to Load (FRAME-2775)”">​</a></h3><div class="info custom-block"><p class="custom-block-title">Description</p><p>Fixes an issue where the widget and pipeline lists failed to load when a widget had invalid configuration. The lists now load as normal, and invalid configuration is rejected when you save.</p></div><h3 id="search-on-the-home-page-keeps-your-location-frame-2751" tabindex="-1">Search on the Home Page Keeps Your Location (FRAME-2751) <a class="header-anchor" href="#search-on-the-home-page-keeps-your-location-frame-2751" aria-label="Permalink to “Search on the Home Page Keeps Your Location (FRAME-2751)”">​</a></h3><div class="info custom-block"><p class="custom-block-title">Description</p><p>Fixes an issue where searching from the home page while in a non-root location took you back to the root location.</p></div><h3 id="widget-action-menu-stays-within-the-widget-frame-2769" tabindex="-1">Widget Action Menu Stays Within the Widget (FRAME-2769) <a class="header-anchor" href="#widget-action-menu-stays-within-the-widget-frame-2769" aria-label="Permalink to “Widget Action Menu Stays Within the Widget (FRAME-2769)”">​</a></h3><div class="info custom-block"><p class="custom-block-title">Description</p><p>Fixes an issue where a widget&#39;s action menu could move outside the widget and overlap other elements when scrolling horizontally.</p></div>`,43)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};